            SshHostKeyType::Dss => "ssh-dss",
            SshHostKeyType::Ecdsa256 => "ecdsa-sha2-nistp256",
            SshHostKeyType::Ecdsa384 => "ecdsa-sha2-nistp384",
            SshHostKeyType::Ecdsa521 => "ecdsa-sha2-nistp521",
            SshHostKeyType::Ed255219 => "ssh-ed25519",
        }
    }

