        match self {
            SshHostKeyType::Unknown => "Unknown",
            SshHostKeyType::Rsa => "RSA",
            SshHostKeyType::Dss => "DSA",
            SshHostKeyType::Ecdsa256 => "ECDSA",
            SshHostKeyType::Ecdsa384 => "ECDSA",
            SshHostKeyType::Ecdsa521 => "ECDSA",
            SshHostKeyType::Ed255219 => "ED25519",
        }
    }
